  flows: OAuthFlows
  store: OAuthConnectionWriter
  write: (text: string) => void
  openBrowser: (url: string) => Promise<void>
  readToken: () => Promise<string>
  startCallbackServer: (options: CallbackServerOptions) => Promise<CallbackServer>
